# JAH whisker-line kernel: horizontal lines vs vertical lines vs blank
K=[[-1,-1,-1],[2,2,2],[-1,-1,-1]]
def total(im):
    h,w=len(im),len(im[0])
    return sum(im[y+ky-1][x+kx-1]*K[ky][kx]
               for y in range(1,h-1) for x in range(1,w-1) for ky in range(3) for kx in range(3))
whisk=[[0]*9 for _ in range(9)]
for y in (2,4,6):
    for x in range(1,8): whisk[y][x]=10          # horizontal whisker-like lines
vert=[[0]*9 for _ in range(9)]
