print("cat silhouette      %.3f      %.1f" % (ear_best(cat()), eye_score([[v*180 for v in row] for row in cat()],(4,4),(4,10))))
print("floppy-ear dog      %.3f      %.1f" % (ear_best(dog()), eye_score([[v*180 for v in row] for row in dog()],(4,4),(4,10))))
print("plain rectangle     %.3f      %.1f" % (ear_best(rect), eye_score([[v*180 for v in row] for row in rect],(4,4),(4,10))))
print("headlight pair      n/a        %.1f  <-- documented confuser" % eye_score(lights,(5,4),(5,10)))
