# JAH edge-to-contour closure: edges -> closing -> connected components
import math
W=H=15
img=[[0]*W for _ in range(H)]
for y in range(H):
    for x in range(W):
        if (x-7)**2+(y-8)**2<=16: img[y][x]=1
for y in range(3,7):
    hw=y-3
    for x in range(4-hw,4+hw+1): img[y][x]=1
    for x in range(10-hw,10+hw+1): img[y][x]=1
GX=[[-1,0,1],[-2,0,2],[-1,0,1]]; GY=[[-1,-2,-1],[0,0,0],[1,2,1]]
E=[[0]*W for _ in range(H)]
for y in range(1,H-1):
    for x in range(1,W-1):
        gx=sum(img[y+ky-1][x+kx-1]*GX[ky][kx] for ky in range(3) for kx in range(3))
        gy=sum(img[y+ky-1][x+kx-1]*GY[ky][kx] for ky in range(3) for kx in range(3))
        E[y][x]=1 if math.hypot(gx,gy)>2.0 else 0
def morph(im, op):
    h,w=len(im),len(im[0]); o=[[0]*w for _ in range(h)]
    for y in range(1,h-1):
        for x in range(1,w-1):
            nb=[im[y+dy][x+dx] for dy in (-1,0,1) for dx in (-1,0,1)]
            o[y][x]=max(nb) if op=='dilate' else min(nb)
    return o
closed=morph(morph(E,'dilate'),'erode')
def components(im):
    h,w=len(im),len(im[0]); seen=[[0]*w for _ in range(h)]; n=0
    for y in range(h):
        for x in range(w):
            if im[y][x] and not seen[y][x]:
                n+=1; stack=[(y,x)]; seen[y][x]=1
                while stack:
                    cy,cx=stack.pop()
                    for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
                        ny,nx=cy+dy,cx+dx
                        if 0<=ny<h and 0<=nx<w and im[ny][nx] and not seen[ny][nx]:
                            seen[ny][nx]=1; stack.append((ny,nx))
    return n
e0=sum(sum(r) for r in E); e1=sum(sum(r) for r in closed)
print("edge pixels before closing:",e0,"| after closing:",e1)
print("connected components after closing:",components(closed))
print("Signature experiment: scattered edges consolidated into countable shapes.")

# JAH kernel-combination algebra: Sobel alone vs junction alone vs cascade
import math
GX=[[-1,0,1],[-2,0,2],[-1,0,1]]; GY=[[-1,-2,-1],[0,0,0],[1,2,1]]
JK=[[-1,-1,2],[-1,2,-1],[2,-1,-1]]
def sobel_map(im):
    h,w=len(im),len(im[0]); m=[[0.0]*w for _ in range(h)]
    for y in range(1,h-1):
        for x in range(1,w-1):
            gx=sum(im[y+ky-1][x+kx-1]*GX[ky][kx] for ky in range(3) for kx in range(3))
            gy=sum(im[y+ky-1][x+kx-1]*GY[ky][kx] for ky in range(3) for kx in range(3))
            m[y][x]=math.hypot(gx,gy)
    return m
def kresp(im,k,cy,cx):
    return sum(im[cy+ky-1][cx+kx-1]*k[ky][kx] for ky in range(3) for kx in range(3))
tip=[[0]*9 for _ in range(9)]                       # crisp ear-tip V
for i in range(5):
    tip[2+i][4-i]=10; tip[2+i][4+i]=10
soft=[[0]*9 for _ in range(9)]                       # blurred brightness V (distractor)
for i in range(5):
    for d in (-1,0,1):
        if 0<=4-i+d<9: soft[2+i][4-i+d]=4
        if 0<=4+i+d<9: soft[2+i][4+i+d]=4
def cascade(im):
    m=sobel_map(im)
    b=[[1 if v>8.0 else 0 for v in row] for row in m]
    return kresp(b,JK,4,4)
for name,im in (("crisp ear tip",tip),("soft distractor",soft)):
    s=max(max(row) for row in sobel_map(im))
    j=kresp(im,JK,4,4)
    print("%-16s sobel=%.1f  junction-alone=%d  cascade=%d" % (name,s,j,cascade(im)))
print("Signature experiment: the cascade widens the true-vs-distractor margin.")
